{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:flutter/material.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  final GlobalKey<CurrencyListPageState> _currencyKey = GlobalKey();
  final GlobalKey<NewsListPageState> _newsKey = GlobalKey();

  static const List<Widget> _pages = <Widget>[
    CurrencyListPage(key: _currencyKey),
    NewsListPage(key: _newsKey),
    ProfilePage(),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  void _refreshAll() {
    final CurrencyListPageState? currencyState = _currencyKey.currentState;
    if (currencyState != null) currencyState.refresh();

    final NewsListPageState? newsState = _newsKey.currentState;
    if (newsState != null) newsState.refresh();
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: PreferredSize(
        preferredSize: const Size.fromHeight(56),
        child: AppBar(
          leadingWidth: double.infinity,
          flexibleSpace: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                loc.refreshAll,
                style: Theme.of(context).textTheme.bodyLarge?.copyWith(
                      fontWeight: FontWeight.bold,
                    ),
              ),
